<?php
$money = static fn(float $v): string => 'KES '.number_format($v, 2);
$summary = $summary ?? [];
$invoices = $invoices ?? [];
$layout = null;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finance | EduSasa</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f6f7fb;color:#172033}.wrap{max-width:1200px;margin:32px auto;padding:0 18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px}.card{background:#fff;border:1px solid #e6e8ef;border-radius:12px;padding:18px}.muted{color:#667085}.value{font-size:24px;font-weight:700;margin-top:8px}table{width:100%;border-collapse:collapse;background:#fff;margin-top:20px}th,td{padding:12px;border-bottom:1px solid #eee;text-align:left}a,.btn{display:inline-block;padding:9px 13px;border-radius:8px;text-decoration:none;background:#172033;color:#fff}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}input{padding:9px;border:1px solid #ccd1db;border-radius:8px}</style></head><body><main class="wrap"><h1>Finance</h1><p class="muted">School fees, invoices and payments.</p><div class="actions"><a href="/finance/invoices/create">Create invoice</a><a href="/finance/categories">Fee categories</a></div><section class="grid"><div class="card"><span class="muted">Billed</span><div class="value"><?= $money((float)($summary['billed']??0)) ?></div></div><div class="card"><span class="muted">Paid</span><div class="value"><?= $money((float)($summary['paid']??0)) ?></div></div><div class="card"><span class="muted">Outstanding</span><div class="value"><?= $money((float)($summary['outstanding']??0)) ?></div></div><div class="card"><span class="muted">Invoices</span><div class="value"><?= (int)($summary['invoices']??0) ?></div></div><div class="card"><span class="muted">Payments</span><div class="value"><?= (int)($summary['payments']??0) ?></div></div></section><form class="actions" method="get"><input name="search" value="<?= htmlspecialchars((string)($_GET['search']??''),ENT_QUOTES) ?>" placeholder="Search invoice, admission no. or student"><button class="btn" type="submit">Search</button></form><table><thead><tr><th>Invoice</th><th>Student</th><th>Date</th><th>Status</th><th>Total</th><th>Balance</th></tr></thead><tbody><?php foreach($invoices as $invoice): ?><tr><td><?= htmlspecialchars($invoice['invoice_no']) ?></td><td><?= htmlspecialchars($invoice['admission_no'].' — '.$invoice['first_name'].' '.$invoice['last_name']) ?></td><td><?= htmlspecialchars($invoice['invoice_date']) ?></td><td><?= htmlspecialchars(ucwords(str_replace('_',' ',$invoice['status']))) ?></td><td><?= $money((float)$invoice['total']) ?></td><td><?= $money((float)$invoice['balance']) ?></td></tr><?php endforeach; if(!$invoices): ?><tr><td colspan="6" class="muted">No invoices found.</td></tr><?php endif; ?></tbody></table></main></body></html>
